/* Despesas mensais recorrentes; geração explícita e sem duplicação. */
(function(root){'use strict';const D=root.Obras,$=s=>document.querySelector(s),h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=v=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(v),id=()=> 'FIX-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,9);let api,month=D.today().slice(0,7),pending=false;
const validMonth=v=>/^\d{4}-(0[1-9]|1[0-2])$/.test(v||'');
function validate(s,x){let recurring=(x.frequency||'monthly')==='monthly',validDate=v=>/^\d{4}-\d{2}-\d{2}$/.test(v||'')&&D.date(v)?.toLocaleDateString('sv-SE')===v;if(!x||typeof x.id!=='string'||!x.id||!String(x.description||'').trim()||!String(x.supplier||'').trim()||!D.num(x.amount)||x.amount<=0||!Number.isSafeInteger(Math.round(x.amount*100))||Math.abs(x.amount*100-Math.round(x.amount*100))>.000001||!['monthly','once'].includes(x.frequency||'monthly')||!D.CATEGORIES.includes(x.category)||typeof x.active!=='boolean')throw Error('Informe descrição, favorecido, valor positivo e tipo de despesa.');if(recurring&&(!Number.isInteger(x.day)||x.day<1||x.day>31||!validMonth(x.start)||x.end&&(!validMonth(x.end)||x.end<x.start)))throw Error('Informe dia de 1 a 31 e período mensal válido.');if(!recurring&&!validDate(x.due))throw Error('Informe o vencimento válido da despesa única.');if(x.project!=='Geral'&&!s.projects.some(p=>p.id===x.project))throw Error('Destino inválido.')}
function validateState(s){let rows=s.fixedExpenses||[];if(!Array.isArray(rows)||new Set(rows.map(x=>x.id)).size!==rows.length)throw Error('Despesas gerais inválidas ou duplicadas.');for(let x of rows)validate(s,x);let seen=new Set();for(let c of s.costs.filter(c=>c.fixedExpense)){if(!rows.some(x=>x.id===c.fixedExpense)||!validMonth(c.fixedMonth))throw Error('Parcela de despesa geral sem cadastro ou competência válida.');let key=c.fixedExpense+'|'+c.fixedMonth;if(seen.has(key))throw Error('Despesa geral duplicada na mesma competência.');seen.add(key);D.validateRecord(s,'costs',c)}return true}
function save(state,record){let s=D.clone(state),x=D.clone(record);validate(s,x);let before=(s.fixedExpenses||[]).find(r=>r.id===x.id)||null,prior=s.costs.filter(c=>c.fixedExpense===x.id);if(before&&prior.length&&(before.project!==x.project||(before.frequency||'monthly')!==(x.frequency||'monthly')))throw Error('Esta despesa já possui lançamentos. Cadastre outra para mudar o destino ou tipo.');s.fixedExpenses=(s.fixedExpenses||[]).filter(r=>r.id!==x.id).concat(x);if(x.frequency==='once'){let old=prior[0],cost={...(old||{}),id:old?.id||'fixed:'+x.id+':once',project:x.project,stage:'',category:x.category,supplier:x.supplier,description:x.description,amount:x.amount,incurred:old?.incurred||0,paid:old?.paid||0,paymentDiscount:old?.paymentDiscount||0,paymentAddition:old?.paymentAddition||0,date:old?.date||D.today(),due:x.due,paidDate:old?.paidDate||'',note:x.note||'',fixedExpense:x.id,fixedMonth:x.due.slice(0,7)};if(old&&['paid','incurred','paymentDiscount','paymentAddition'].some(k=>Number(old[k]||0)>0)&&['amount','due','project','category','supplier','description'].some(k=>old[k]!==cost[k]))throw Error('Esta despesa já possui baixa. Corrija o pagamento antes de alterar valores ou vencimento.');D.validateRecord(s,'costs',cost);s.costs=s.costs.filter(c=>c.fixedExpense!==x.id).concat(cost)}validateState(s);s.history.unshift({id:id(),time:new Date().toISOString(),kind:'fixedExpenses',record:x.id,action:before?'Despesa geral atualizada':'Despesa geral cadastrada',before,after:x});return s}
function generate(state,competence,project='all'){if(!validMonth(competence))throw Error('Selecione um mês válido.');let s=D.clone(state),created=[];for(let x of s.fixedExpenses||[]){if(x.frequency==='once'||!x.active||x.start>competence||x.end&&x.end<competence||project!=='all'&&x.project!==project||s.costs.some(c=>c.fixedExpense===x.id&&c.fixedMonth===competence))continue;validate(s,x);let last=Number(D.addDays(D.addMonths(competence+'-01',1),-1).slice(8)),due=competence+'-'+String(Math.min(x.day,last)).padStart(2,'0'),cost={id:'fixed:'+x.id+':'+competence,project:x.project,stage:'',category:x.category,supplier:x.supplier,description:x.description+' · '+competence,amount:x.amount,incurred:0,paid:0,paymentDiscount:0,paymentAddition:0,date:D.today(),due,paidDate:'',note:x.note||'',fixedExpense:x.id,fixedMonth:competence};D.validateRecord(s,'costs',cost);s.costs.push(cost);created.push(cost)}validateState(s);if(created.length)s.history.unshift({id:id(),time:new Date().toISOString(),kind:'fixedExpenseGeneration',record:competence,action:'Despesas gerais geradas em Contas a pagar',before:null,after:created});return {state:s,count:created.length}}
function render(s,project){let rows=(s.fixedExpenses||[]).filter(x=>project==='all'||x.project===project),bills=s.costs.filter(c=>c.fixedExpense&&c.fixedMonth===month&&(project==='all'||c.project===project));return '<header class="page-head"><div><h1>Despesas gerais</h1><p>Despesas da empresa sem vínculo com obras: multas e gastos únicos, água, luz e outras despesas recorrentes. Os pagamentos são registrados em Contas a pagar.</p></div><button class="button primary" data-action="fixed-new">+ Despesa geral</button></header><section class="panel"><div class="panel-body"><label>Competência<input type="month" id="fixedMonth" value="'+h(month)+'"></label><button type="button" class="button primary" id="fixedGenerate">Gerar mês em Contas a pagar</button><p>Gera somente as contas ativas no período escolhido. Repetir a geração não duplica as contas já lançadas.</p><p><strong>Gerado no mês: '+money(D.sum(bills,c=>c.amount))+'</strong> · Pago: '+money(D.sum(bills,c=>c.paid))+' · Em aberto: '+money(D.sum(bills,D.costBalance))+'</p><a class="button secondary" href="#payables">Abrir Contas a pagar</a><p id="fixedError" role="alert" class="red-text"></p></div></section><div class="table-wrap"><table><thead><tr><th>Descrição / fornecedor</th><th>Destino</th><th>Valor</th><th>Tipo / vencimento</th><th>Período</th><th>Situação</th><th></th></tr></thead><tbody>'+rows.map(x=>'<tr><td>'+h(x.description)+'<br>'+h(x.supplier)+'</td><td>'+h(x.project==='Geral'?'Despesa geral da empresa':s.projects.find(p=>p.id===x.project)?.name)+'</td><td>'+money(x.amount)+'</td><td>'+h(x.frequency==='once'?'Única · '+x.due:'Mensal · dia '+x.day)+'</td><td>'+h(x.frequency==='once'?x.due:x.start+' a '+(x.end||'sem término'))+'</td><td>'+h(x.frequency==='once'?'Lançada':x.active?'Ativa':'Inativa')+'</td><td><button class="button secondary" data-action="fixed-edit:'+h(x.id)+'">Editar</button>'+(x.frequency==='once'?'':'<button class="button secondary" data-action="fixed-toggle:'+h(x.id)+'">'+(x.active?'Desativar':'Ativar')+'</button>')+'</td></tr>').join('')+'</tbody></table></div>'+(!rows.length?'<p class="empty">Cadastre a primeira despesa geral. Escolha uma despesa única ou uma recorrência mensal, sempre no destino Geral.</p>':'')}
async function commit(next,message){pending=true;try{if(await api.save(next)===false)throw Error('O servidor não confirmou o salvamento. Atualize antes de tentar novamente.');api.render();api.toast(message)}finally{pending=false}}
function open(recordId){let snapshot=D.clone(api.getState()),x=D.clone((snapshot.fixedExpenses||[]).find(x=>x.id===recordId)||{id:id(),project:'Geral',frequency:'once',due:D.today(),description:'',supplier:'',amount:0,category:'Indiretos e tributos',day:10,start:month,end:'',active:true,note:''}),field=(key,label,type='text')=>'<label>'+label+'<input data-fixed-field="'+key+'" type="'+type+'" '+(key==='amount'?'inputmode="decimal"':'')+' value="'+h(key==='amount'?x.amount.toFixed(2).replace('.',','):(x[key]||''))+'"></label>';$('#readerTitle').textContent='Despesa geral';$('#readerContent').innerHTML='<form id="fixedForm" class="reader-page fixed-editor"><div class="wf-form">'+field('description','Descrição *')+field('supplier','Fornecedor / favorecido *')+'<p>Destino: <strong>'+h(x.project==='Geral'?'Geral':snapshot.projects.find(p=>p.id===x.project)?.name||x.project)+'</strong></p><label>Tipo de despesa<select data-fixed-field="frequency"><option value="once" '+(x.frequency==='once'?'selected':'')+'>Única (multa ou gasto eventual)</option><option value="monthly" '+(x.frequency!=='once'?'selected':'')+'>Recorrente mensal (água, luz etc.)</option></select></label><label>Categoria<select data-fixed-field="category">'+D.CATEGORIES.map(c=>'<option '+(c===x.category?'selected':'')+'>'+h(c)+'</option>').join('')+'</select></label>'+field('amount','Valor (R$) *')+'<div id="generalOnceFields">'+field('due','Vencimento da despesa única *','date')+'</div><div id="generalRecurringFields">'+field('day','Dia de vencimento (1 a 31) *','number')+field('start','Primeira competência *','month')+field('end','Última competência (opcional)','month')+'</div>'+field('note','Observações')+'</div><p class="section-note">Despesa única entra em Contas a pagar ao salvar. Para recorrentes, use Gerar mês. Em meses mais curtos, o vencimento usa o último dia. Valores já gerados são preservados.</p><p id="fixedFormError" role="alert" class="red-text"></p><button type="submit" class="button primary">Salvar despesa geral</button></form>';$('#reader').showModal();let frequency=$('[data-fixed-field="frequency"]'),toggle=()=>{let once=(frequency.value||x.frequency||'monthly')==='once';$('#generalOnceFields').hidden=!once;$('#generalRecurringFields').hidden=once};frequency.onchange=toggle;toggle();$('#fixedForm').onsubmit=async e=>{e.preventDefault();if(pending)return;try{if(JSON.stringify(api.getState())!==JSON.stringify(snapshot))throw Error('Os dados mudaram. Reabra o cadastro.');let value=D.clone(x);for(let el of document.querySelectorAll('[data-fixed-field]'))value[el.dataset.fixedField]=el.dataset.fixedField==='amount'?root.EngefexCurrency.parse(el.value):el.dataset.fixedField==='day'?Number(el.value):el.value.trim();let next=save(snapshot,value);await commit(next,'Despesa geral salva.');$('#reader').close()}catch(e){$('#fixedFormError').textContent=e.message}}}
function bind(){if($('#fixedMonth'))$('#fixedMonth').onchange=e=>{month=e.target.value;api.render()};if($('#fixedGenerate'))$('#fixedGenerate').onclick=async()=>{if(pending)return;try{let result=generate(api.getState(),month,api.getProject());if(!result.count)return api.toast('Nenhuma conta nova para gerar nesta competência.');await commit(result.state,result.count+' contas geradas em Contas a pagar.')}catch(e){$('#fixedError').textContent=e.message}}}
root.EngefexFixedExpenses={validateState,save,generate,render,bind,busy:()=>pending,isDirty:()=>!!$('#reader')?.open&&!!$('#readerContent .fixed-editor'),init:bridge=>api=bridge,handle(action){if(pending&&action?.startsWith('fixed-'))return true;if(action==='fixed-new'){open();return true}if(action?.startsWith('fixed-edit:')){open(action.slice(11));return true}if(action?.startsWith('fixed-toggle:')){let s=api.getState(),x=(s.fixedExpenses||[]).find(x=>x.id===action.slice(13));if(x)commit(save(s,{...x,active:!x.active}),'Situação da despesa geral atualizada.').catch(e=>api.toast(e.message));return true}return false}};
})(typeof window==='undefined'?globalThis:window);
